--liquibase formatted sql

--changeset ferrefix:catalogo-001 logicalFilePath:db/changelog/001-schema.sql
CREATE TABLE productos (
    id_producto VARCHAR(36) PRIMARY KEY,
    version BIGINT NOT NULL DEFAULT 0,
    nombre VARCHAR(160) NOT NULL,
    marca VARCHAR(100) NOT NULL,
    categoria VARCHAR(80) NOT NULL,
    precio_venta DECIMAL(12,0) NOT NULL,
    stock INT NOT NULL,
    descripcion VARCHAR(4000) NOT NULL,
    imagen VARCHAR(255) NOT NULL,
    activo BOOLEAN NOT NULL DEFAULT TRUE,
    fecha_creacion DATETIME(6) NOT NULL,
    CONSTRAINT ck_producto_stock CHECK (stock >= 0),
    CONSTRAINT ck_producto_precio CHECK (precio_venta >= 0)
);
CREATE INDEX idx_productos_activo ON productos(activo);
CREATE TABLE producto_especificaciones (
    producto_id VARCHAR(36) NOT NULL,
    clave VARCHAR(120) NOT NULL,
    valor VARCHAR(500) NOT NULL,
    PRIMARY KEY (producto_id, clave),
    CONSTRAINT fk_especificaciones_producto FOREIGN KEY (producto_id) REFERENCES productos(id_producto)
);

--changeset ferrefix:catalogo-002 logicalFilePath:db/changelog/002-productos-iniciales.sql

--changeset ferrefix:catalogo-003 logicalFilePath:db/changelog/003-descripciones-producto.sql
ALTER TABLE productos
    RENAME COLUMN descripcion TO descripcion_larga,
    ADD COLUMN descripcion_corta VARCHAR(300) NOT NULL DEFAULT '';

--changeset ferrefix:catalogo-004 logicalFilePath:db/changelog/004-presentacion-producto.sql
ALTER TABLE productos
    ADD COLUMN unidad_venta VARCHAR(20) NOT NULL DEFAULT 'unidad',
    ADD COLUMN contenido_presentacion VARCHAR(120) NOT NULL DEFAULT '1 unidad',
    ADD CONSTRAINT ck_producto_unidad_venta CHECK (unidad_venta IN ('unidad','caja','bolsa','kilo','pack','saco','rollo','metro','litro'));

--changeset ferrefix:catalogo-004-tornillos logicalFilePath:db/changelog/004-presentacion-producto.sql
